ExtTextOut(hdc, 10, 40, 0, NULL, TEXT("PROP_ICON"), 
 _tcslen(TEXT("PROP_ICON")), NULL); 
DrawIcon(hdc, 90, 40, (HICON)hIconProp); 
hCursProp = (HCURSOR) GetProp(hwndSubclass, TEXT("PROP_CURSOR")); 
