 _tcslen(TEXT("PROP_CURSOR")), NULL); 
DrawIcon(hdc, 110, 85, (HICON)hCursProp); 
lpFilename = (TCHAR*) GetProp(hwndSubclass, TEXT("PROP_BUFFER")); 
hr = StringCchPrintf(tchBuffer, MAX_PATH, TEXT("Path to file: %s"),
